 8→/**
 9→ * Hook that handles clicks outside of the passed ref.
10→ */
11→export const useOutsideClickHandler = (
12→  ref: React.RefObject<HTMLElement> | Array<React.RefObject<HTMLElement>>,
13→  onOutsideClick: (event?: MouseEvent) => void,
14→) => {
15→  const hasClickedOutside = React.useCallback((ref: React.RefObject<HTMLElement>, event: MouseEvent) => {
16→    const target: null | EventTarget = event.target;
17→    return ref.current && target instanceof Node && !ref.current.contains(target);
18→  }, []);
19→  
20→  React.useEffect(() => {
21→    const handleClickOutside = (event: MouseEvent) => {
22→      if ((Array.isArray(ref) && ref.every(r => hasClickedOutside(r, event)))
23→        || (!Array.isArray(ref) && hasClickedOutside(ref, event))) {
24→        onOutsideClick();
25→      }
26→    };
27→    
28→    // Bind the event listener
29→    document.addEventListener('mousedown', handleClickOutside);
30→    
31→    return () => {
32→      // Unbind the event listener on clean up
33→      document.removeEventListener('mousedown', handleClickOutside);
34→    };
35→  }, [ref, hasClickedOutside, onOutsideClick]);
36→};
