  5→import * as React from 'react';
  6→import { createPortal } from 'react-dom';
  7→import { mergeRefs } from '../../../util/reactUtil.ts';
  8→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
  9→
 10→import { type BannerVariant, Banner } from '../../containers/Banner/Banner.tsx';
 11→import { TopLayerContext, useActiveModalDialog } from '../../util/overlays/TopLayerManager.tsx';
 12→
 13→import { type ToastId, type ToastDescriptor, type ToastOptions, type ToastStorage, ToastStore } from './ToastStore.ts';
 14→
 15→import cl from './ToastProvider.module.scss';
 16→
 17→
 18→export { cl as ToasterClassNames };
 19→
 20→export type { ToastDescriptor };
 21→
 22→export const createToastNotifier = (toastStore: ToastStore) => {
 23→  const notify = (toast: ToastDescriptor) => {
 24→    // If a toast with the same dedupeKey is already active, do not create another one.
 25→    if (toastStore.hasActiveDedupeKey(toast)) { return; }
 26→    const toastId = toastStore.uniqueId();
 27→    toastStore.announceToast(toastId, toast);
 28→  };
 29→  const notifyVariant = (
 30→    variant: BannerVariant,
 31→    toast: string | Omit<ToastDescriptor, 'variant'>,
 32→    options?: undefined | ToastOptions,
 33→  ) => {
 34→    const descriptor: ToastDescriptor = typeof toast === 'string'
 35→      ? { variant, message: toast, options }
 36→      : { ...toast, variant, options: { ...toast.options, ...(options ?? {}) } };
 37→    notify(descriptor);
 38→  };
 39→  return Object.assign(notify, {
 40→    info: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
 41→      notifyVariant('info', toast, options),
 42→    warning: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
 43→      notifyVariant('warning', toast, options),
 44→    error: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
 45→      notifyVariant('error', toast, options),
 46→    success: (toast: string | Omit<ToastDescriptor, 'variant'>, options?: undefined | ToastOptions) =>
 47→      notifyVariant('success', toast, options),
 48→    dismiss: (toastId: ToastId) => {
 49→      toastStore.dismissToast(toastId);
 50→    },
 51→    dismissAll: () => {
 52→      toastStore.dismissAllToasts();
 53→    },
 54→  });
 55→};
 56→
 57→export const Toast = (props: React.ComponentProps<typeof Banner>) => {
 58→  return (
 59→    <Banner
 60→      trimmed
 61→      compact={false}
 62→      showCloseAction
 63→      {...props}
 64→      className={cx(cl['bk-toast'], props.className)}
 65→    />
 66→  )
 67→};
 68→
 69→export const ToastCopyAction = ({ toast }: { toast: ToastDescriptor }) => {
 70→  const defaultLabel = 'Copy';
 71→  const [label, setLabel] = React.useState(defaultLabel);
 72→  
 73→  const handleCopy = React.useCallback(async (message: string) => {
 74→    try {
 75→      // Idea: use `write()` with HTML mime type to copy arbitrary content? Could get the `innerHTML` through a ref.
 76→      if (navigator.clipboard.writeText) {
 77→        await navigator.clipboard.writeText(message);
 78→      }
 79→      
 80→      setLabel('Copied!');
 81→    } catch (error: unknown) {
 82→      setLabel('Error: unable to copy');
 83→    }
 84→  }, []);
 85→  
 86→  const message = toast.message;
 87→  
 88→  // Currently don't support copying unless the message is a string
 89→  if (typeof message !== 'string') { return null; }
 90→  
 91→  return (
 92→    <Banner.ActionIcon
 93→      icon="copy"
 94→      label={label}
 95→      onPress={() => handleCopy(message)} // Note: careful to return the promise here to `onPress`
 96→      onMouseLeave={() => {
 97→        // Reset the label after exit animation had a chance to complete
 98→        window.setTimeout(() => { setLabel(defaultLabel); }, 500);
 99→      }}
100→    />
101→  );
102→};
103→
104→export type ToasterProps = React.PropsWithChildren<ComponentProps<'section'>>;
105→/**
106→ * Renders any current toast notifications.
107→ */
108→export const Toaster = (props: ToasterProps) => {
109→  const { ...propsRest } = props;
110→  const { toastStore } = useToastContext();
111→  
112→  // Cache the toasts we read from the store.
113→  // Note: initialize function must read the toasts synchronously from the store, we cannot wait until the first
114→  // `subscribe()` kicks in, because then we spend one render cycle without state (which causes flickering).
115→  const [toasts, setToasts] = React.useState<ToastStorage>(() => toastStore.toasts());
116→  
117→  React.useEffect(() => {
118→    return toastStore.subscribe(toasts => {
119→      // FIXME: it would be nice to do this in a view transition so that things like toast shifting animates properly.
120→      // However view transitions cause some issues, e.g. click events don't fire while the transition is happening.
121→      //startViewTransition(() => {
122→        setToasts(toasts);
123→      //});
124→    });
125→  }, [toastStore]);
126→  
127→  // Pause auto-close when the page is not currently visible by the user
128→  React.useEffect(() => {
129→    const controller = new AbortController();
130→    
131→    document.addEventListener('visibilitychange', () => {
132→      if (document.visibilityState === 'visible') {
133→        toastStore.onPageVisible();
134→      } else {
135→        toastStore.onPageHide();
136→      }
137→    }, { signal: controller.signal });
138→    
139→    return () => { controller.abort(); };
140→  }, [toastStore]);
141→  
142→  const containerRef = React.useRef<null | React.ComponentRef<'section'>>(null);
143→  const openPopover = React.useCallback((container: null | HTMLElement) => {
144→    if (container && container.isConnected) {
145→      try {
146→        container.hidePopover();
147→        container.showPopover();
148→      } catch (error: unknown) {
149→        console.error(`Failed to open Toaster`, error);
150→      }
151→    }
152→  }, []);
153→  
154→  // Ref callback to enforce that the Toaster is always rendered as a popover
155→  const enforcePopoverOpen: React.RefCallback<React.ComponentRef<'section'>> = container => {
156→    containerRef.current = container;
157→    openPopover(container);
158→  };
159→  
160→  const modalDialogContext = React.use(TopLayerContext);
161→  React.useEffect(() => {
162→    if (modalDialogContext === null) { throw new Error(`Cannot read ModalDialogContext: missing provider.`); }
163→    return modalDialogContext.modalDialogStack.subscribe(() => { openPopover(containerRef.current); });
164→  }, [modalDialogContext, openPopover]);
165→  
166→  return (
167→    <section
168→      aria-label="Notifications"
169→      tabIndex={-1} // Do not include in normal tab order
170→      aria-live="polite"
171→      aria-relevant="additions text"
172→      aria-atomic="false"
173→      popover="manual"
174→      {...propsRest}
175→      ref={mergeRefs(enforcePopoverOpen, propsRest.ref)}
176→      className={cx(
177→        'bk',
178→        cl['bk-toaster'],
179→        propsRest.className,
180→      )}
181→    >
182→      {Object.entries(toasts).map(([toastKey, { metadata, descriptor: toast }]) => {
183→        const toastId = toastStore.idFromKey(toastKey);
184→        return (
185→          <Toast
186→            key={toastKey}
187→            className={cx({
188→              [cl['bk-toast--skip-entry']]: toastStore.shouldSkipEntryAnimation(toastId),
189→            })}
190→            variant={toast.variant}
191→            title={toast.title}
192→            hidden={metadata.dismissed}
193→            actions={
194→              <ToastCopyAction toast={toast}/>
195→            }
196→            onClose={() => {
197→              toastStore.dismissToast(toastId);
198→            }}
199→            // Handle dismiss signals (e.g. clicking or tapping on the toast)
200→            onClick={event => { event.stopPropagation(); toastStore.dismissToast(toastId); }}
201→            // Handle interest signals (e.g. hovering over the toast)
202→            onMouseEnter={event => { event.stopPropagation(); toastStore.pauseAutoClose(toastId); }}
203→            onTouchStart={event => { event.stopPropagation(); toastStore.pauseAutoClose(toastId); }}
204→            onMouseLeave={event => { event.stopPropagation(); toastStore.resumeAutoClose(toastId); }}
205→            onTouchEnd={event => { event.stopPropagation(); toastStore.resumeAutoClose(toastId); }}
206→          >
207→            {toast.message}
208→          </Toast>
209→        );
210→      })}
211→    </section>
212→  );
213→};
214→
215→
216→export type ToastContext = { toastStore: ToastStore, notify: (toast: ToastDescriptor) => void };
217→export const ToastContext = React.createContext<null | ToastContext>(null);
218→export const useToastContext = (): ToastContext => {
219→  const context = React.use(ToastContext);
220→  if (context === null) { throw new Error(`Missing ToastContext`); }
221→  return context;
222→};
223→
224→// A single global instance, to be used with `<ToastProvider global/>`
225→export const globalToastStore = new ToastStore();
226→export const notify = createToastNotifier(globalToastStore);
227→
228→type ToastProviderProps = React.PropsWithChildren<{ global?: boolean }>;
229→export const ToastProvider = ({ global = false, children }: ToastProviderProps) => {
230→  const activeModalDialog = useActiveModalDialog();
231→  
232→  // Note: we need to be careful to not store toasts in `useState()` in this component, otherwise the entire
233→  // subtree will be rerendered on every change. Use the Observable pattern instead.
234→  // https://www.fullstory.com/blog/why-fullstory-uses-observables-in-react
235→  
236→  const toastStoreRef = React.useRef<null | ToastStore>(global ? globalToastStore : null);
237→  const toastStore = toastStoreRef.current ?? new ToastStore(); // Lazy initialization
238→  
239→  const toastContext = React.useMemo(() => ({
240→    toastStore,
241→    notify: createToastNotifier(toastStore),
242→  }), [toastStore]);
243→  
244→  return (
245→    <ToastContext value={toastContext}>
246→      {children}
247→      {/*
248→      Render the toasts in the top-most modal `<dialog>`, to work around browser limitations where only the `<dialog>`
249→      element and its descendants are interactive (everything else is inert).
250→      */}
251→      {createPortal(<Toaster/>, activeModalDialog?.dialogRef?.current ?? window.document.body)}
252→    </ToastContext>
253→  );
254→};
255→
256→export const useNotify = () => {
257→  return useToastContext().notify;
258→};
