271→  describe('custom props', () => {
272→    test('should pass through additional HTML attributes', () => {
273→      render(<Button data-label="custom-button" title="Custom Title" label="Custom" />);
274→      
275→      const button = screen.getByTestId('custom-button');
276→      expect(button).toHaveAttribute('title', 'Custom Title');
277→    });
278→    
279→    test('should merge custom className with default classes', () => {
280→      render(<Button className="custom-class" label="Custom Class" />);
281→      
282→      const button = screen.getByRole('button');
283→      expect(button).toHaveClass('bk', cl['bk-button'], 'custom-class');
284→    });
285→  });
286→  
287→  describe('accessibility', () => {
288→    test('should be focusable by default', () => {
289→      render(<Button label="Focusable" />);
290→      
291→      const button = screen.getByRole('button');
292→      button.focus();
293→      expect(button).toHaveFocus();
